(function(){
const api=window.jali,$=s=>document.querySelector(s),clone=v=>v?{...v}:null,key=p=>p.r+':'+p.c;
let clipboard=null,pending=null,gesture=null,addMode=false;
function status(message){$('#clipboardStatus').textContent=message}
function refresh(){const n=api.selectedCells.length;for(const id of ['copySelection','cutSelection','moveSelection'])$('#'+id).disabled=!n;$('#pasteSelection').disabled=!clipboard;$('#cancelPlacement').hidden=!pending;$('#addSelection').setAttribute('aria-pressed',String(addMode));$('#clipboardTools').classList.toggle('placing',!!pending)}
function patch(){const points=api.selectedCells,b=api.selectionBounds;if(!points.length)return null;return {height:b.r2-b.r1+1,width:b.c2-b.c1+1,source:{r:b.r1,c:b.c1},cells:points.map(p=>({r:p.r-b.r1,c:p.c-b.c1,cell:clone(api.state.cells[p.r][p.c])}))}}
function cancel(){pending=null;$('#transferGhost')?.remove();refresh();status('Drag to select · Shift adds · Ctrl/⌘ toggles')}
function copy(cut=false){cancel();const data=patch();if(!data)return false;clipboard=data;if(cut)api.transaction(s=>{for(const p of data.cells)s.cells[data.source.r+p.r][data.source.c+p.c]=null});refresh();status((cut?'Cut ':'Copied ')+data.cells.length+' cells in this tab. Paste, then choose the top-left destination.');return true}
function fits(data,r,c){return Number.isInteger(r)&&Number.isInteger(c)&&r>=0&&c>=0&&r+data.height<=api.state.cells.length&&c+data.width<=api.state.cells[0].length}
function preview(){if(!pending)return;$('#transferGhost')?.remove();const svg=$('#drawing svg');if(!svg)return;const {data,r,c}=pending,good=fits(data,r,c),pitch=100+api.state.joint/(api.state.blockSize*25.4)*100,g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='transferGhost';g.setAttribute('pointer-events','none');for(const p of data.cells){const tile=document.createElementNS('http://www.w3.org/2000/svg','g');tile.setAttribute('transform',`translate(${(c+p.c)*pitch} ${(r+p.r)*pitch})`);tile.setAttribute('opacity','.75');if(p.cell){const known=svg.querySelector(`.cell[data-row="${data.source.r+p.r}"][data-col="${data.source.c+p.c}"]`);if(known&&JSON.stringify(api.state.cells[data.source.r+p.r]?.[data.source.c+p.c])===JSON.stringify(p.cell))tile.innerHTML=known.innerHTML;else tile.innerHTML=api.cellSVG(p.cell.type,p.cell.rotation)}else tile.innerHTML='<rect width="100" height="100" fill="#dce2d3" fill-opacity=".7" stroke="#65785a" stroke-dasharray="8 5"/>';tile.innerHTML+=`<rect x="1" y="1" width="98" height="98" fill="none" stroke="${good?'#2c7251':'#c43a2d'}" stroke-width="5"/>`;g.appendChild(tile)}svg.appendChild(g);status((pending.move?'Move':'Paste')+' '+data.cells.length+' cells · row '+(r+1)+', column '+(c+1)+(good?' · click / Enter to place; replaces destination cells':' · does not fit — choose a destination inside the wall'));}
function start(move=false){cancel();const data=move?patch():clipboard;if(!data)return false;if(api.view!=='2d')$('#view2d').click();api.setTool('select');const b=api.selectionBounds;pending={data:JSON.parse(JSON.stringify(data)),move,r:b?.r1??0,c:b?.c1??0};refresh();preview();return true}
function commit(r=pending?.r,c=pending?.c){if(!pending)return false;const {data,move}=pending;if(!fits(data,r,c)){status('The entire selection must fit inside the wall. Choose another destination.');return false}if(move&&data.cells.some(p=>JSON.stringify(api.state.cells[data.source.r+p.r]?.[data.source.c+p.c])!==JSON.stringify(p.cell))){cancel();status('The source changed. Select the cells again before moving.');return false}if(move&&r===data.source.r&&c===data.source.c){cancel();return true}api.transaction(s=>{if(move)for(const p of data.cells)s.cells[data.source.r+p.r][data.source.c+p.c]=null;for(const p of data.cells)s.cells[r+p.r][c+p.c]=clone(p.cell)});pending=null;$('#transferGhost')?.remove();api.setSelection(data.cells.map(p=>({r:r+p.r,c:c+p.c})));refresh();status((move?'Moved ':'Pasted ')+data.cells.length+' cells. Undo restores the previous wall.');return true}
function nudge(dr,dc){if(pending){pending.r+=dr;pending.c+=dc;preview();return true}const data=patch();if(!data)return false;if(!fits(data,data.source.r+dr,data.source.c+dc)){status('Selection cannot move beyond the wall.');return false}pending={data,move:true,r:data.source.r+dr,c:data.source.c+dc};return commit()}
function all(){if(api.view!=='2d')$('#view2d').click();api.setTool('select');api.setSelection(api.state.cells.flatMap((row,r)=>row.map((_,c)=>({r,c}))));status('All cells selected.');return true}
$('#copySelection').onclick=()=>copy();$('#cutSelection').onclick=()=>copy(true);$('#pasteSelection').onclick=()=>start();$('#moveSelection').onclick=()=>start(true);$('#cancelPlacement').onclick=cancel;$('#addSelection').onclick=()=>{cancel();addMode=!addMode;$('#view2d').click();api.setTool('select');refresh();status(addMode?'Multi-select on: tap cells to toggle or drag to add a region.':'Drag replaces selection. Shift adds; Ctrl/⌘ toggles.')};
const drawing=$('#drawing');
drawing.addEventListener('pointerdown',e=>{if(e.button!==0||e.isPrimary===false||window.jaliMobile?.panel)return;const cell=e.target.closest('.cell');if(!cell||api.tool==='pan')return;const p={r:+cell.dataset.row,c:+cell.dataset.col};if(pending){e.preventDefault();e.stopImmediatePropagation();commit(p.r,p.c);return}if(api.tool!=='select')return;e.preventDefault();e.stopImmediatePropagation();const base=api.selectedCells;gesture={anchor:p,base,mode:e.ctrlKey||e.metaKey||addMode?'toggle':e.shiftKey?'add':'replace',pointerId:e.pointerId};applyRectangle(p);},true);
function applyRectangle(to){const g=gesture;if(!g)return;const next=new Map(g.mode==='replace'?[]:g.base.map(p=>[key(p),p]));for(let r=Math.min(g.anchor.r,to.r);r<=Math.max(g.anchor.r,to.r);r++)for(let c=Math.min(g.anchor.c,to.c);c<=Math.max(g.anchor.c,to.c);c++){const p={r,c},k=key(p);if(g.mode==='toggle'&&next.has(k))next.delete(k);else next.set(k,p)}api.setSelection([...next.values()])}
drawing.addEventListener('pointermove',e=>{const cell=(document.elementFromPoint(e.clientX,e.clientY)||e.target).closest?.('.cell');if(!cell)return;if(pending){e.stopImmediatePropagation();pending.r=+cell.dataset.row;pending.c=+cell.dataset.col;preview()}else if(gesture&&gesture.pointerId===e.pointerId){e.stopImmediatePropagation();applyRectangle({r:+cell.dataset.row,c:+cell.dataset.col})}},true);
for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>gesture=null);
drawing.addEventListener('keydown',e=>{if(!pending||!['Enter',' '].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();commit()},true);
drawing.addEventListener('pointerleave',()=>$('#transferGhost')?.remove());
window.addEventListener('jali-select',refresh);window.addEventListener('jali-rendered',()=>{refresh();if(pending)preview()});window.addEventListener('jali-tool',()=>{if(pending)cancel()});window.addEventListener('jali-view',()=>{if(pending&&api.view!=='2d')cancel()});
api.clipboard={copy:()=>copy(),cut:()=>copy(true),paste:()=>start(),move:()=>start(true),commit,cancel,nudge,selectAll:all,get pending(){return !!pending},get hasContent(){return !!clipboard}};refresh();
})();
